import pytest
from candidate import below_threshold


class TestBelowThreshold:
    def test_all_elements_below_threshold_returns_true(self):
        assert below_threshold([1, 2, 4, 10], 100) is True

    def test_one_element_above_threshold_returns_false(self):
        assert below_threshold([1, 20, 4, 10], 5) is False

    def test_one_element_equal_to_threshold_returns_false(self):
        assert below_threshold([1, 5, 4, 10], 5) is False

    def test_empty_list_returns_true(self):
        assert below_threshold([], 100) is True

    def test_single_element_below_threshold_returns_true(self):
        assert below_threshold([5], 10) is True

    def test_single_element_equal_to_threshold_returns_false(self):
        assert below_threshold([10], 10) is False

    def test_single_element_above_threshold_returns_false(self):
        assert below_threshold([15], 10) is False

    def test_all_elements_above_threshold_returns_false(self):
        assert below_threshold([100, 200, 300], 50) is False

    def test_negative_elements_below_positive_threshold(self):
        assert below_threshold([-1, -2, -3], 0) is True

    def test_negative_elements_below_negative_threshold(self):
        assert below_threshold([-10, -20, -30], -5) is True

    def test_negative_element_above_negative_threshold(self):
        assert below_threshold([-1, -2, -3], -2) is False

    def test_negative_element_equal_to_negative_threshold(self):
        assert below_threshold([-1, -5, -3], -5) is False

    def test_zero_threshold_with_positive_elements(self):
        assert below_threshold([1, 2, 3], 0) is False

    def test_zero_threshold_with_negative_elements(self):
        assert below_threshold([-1, -2, -3], 0) is True

    def test_zero_threshold_with_zero_element(self):
        assert below_threshold([0, -1, -2], 0) is False

    def test_mixed_positive_and_negative_all_below(self):
        assert below_threshold([-5, -1, 0, 1, 5], 10) is True

    def test_mixed_positive_and_negative_one_above(self):
        assert below_threshold([-5, -1, 0, 1, 15], 10) is False

    def test_large_numbers_all_below(self):
        assert below_threshold([1000000, 2000000, 3000000], 10000000) is True

    def test_large_numbers_one_above(self):
        assert below_threshold([1000000, 20000000, 3000000], 10000000) is False

    def test_float_elements_below_threshold(self):
        assert below_threshold([1.1, 2.2, 3.3], 5) is True

    def test_float_element_equal_to_threshold(self):
        assert below_threshold([1.0, 2.0, 5.0], 5) is False

    def test_float_threshold_with_int_elements(self):
        assert below_threshold([1, 2, 3], 3.5) is True

    def test_float_threshold_with_element_at_boundary(self):
        assert below_threshold([1, 2, 3], 3.0) is False

    def test_threshold_is_zero_with_only_negatives(self):
        assert below_threshold([-0.5, -1.5], 0) is True

    def test_consecutive_elements_first_below_rest_above(self):
        assert below_threshold([1, 2, 10, 20], 5) is False

    def test_last_element_equals_threshold(self):
        assert below_threshold([1, 2, 3, 10], 10) is False

    def test_all_elements_just_below_threshold(self):
        assert below_threshold([98, 99, 99], 100) is True

    def test_bool_true_below_threshold_two(self):
        assert below_threshold([True, True, False], 2) is True

    def test_bool_true_equal_to_threshold_one(self):
        assert below_threshold([True, False, 0], 1) is False

    def test_single_zero_below_positive_threshold(self):
        assert below_threshold([0], 1) is True

    def test_duplicate_elements_all_below(self):
        assert below_threshold([3, 3, 3], 4) is True

    def test_duplicate_elements_one_at_threshold(self):
        assert below_threshold([3, 4, 3], 4) is False
